import * as THREE from '../vendor/three.module.js';

const canvas = document.querySelector('#game');
const scene = new THREE.Scene();
const fogColor = new THREE.Color(0x171f1d);
scene.background = fogColor;
scene.fog = new THREE.FogExp2(fogColor, 0.022);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 150);
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const mat = (color, roughness=.85, metalness=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const mats = {
  earth: mat(0x353931), road: mat(0x39362f), grass: mat(0x242c24), stone: mat(0x625e51),
  wood: mat(0x40372c), darkWood: mat(0x292a23), plaster: mat(0x666051), roof: mat(0x302d28),
  metal: mat(0x55574f,.58,.52), glass: new THREE.MeshStandardMaterial({color:0x171d1a,roughness:.27,metalness:.18}),
  gold: mat(0xb3945f,.5,.5), skin: mat(0x98745c), skin2: mat(0x745a4d), hair: mat(0x282522),
  coat: mat(0x38443d), coatDark: mat(0x242b28), trousers: mat(0x292d2b), boot: mat(0x171a18),
  red: mat(0x75463b), infected: mat(0x585943), bone: mat(0xa59779),
};
const boxGeo = new THREE.BoxGeometry(1,1,1);
const sphereGeo = new THREE.SphereGeometry(1,16,12);
const cylGeo = new THREE.CylinderGeometry(1,1,1,10);
function mesh(geometry, material, parent, pos=[0,0,0], scale=[1,1,1], cast=true) {
  const o = new THREE.Mesh(geometry,material); o.position.set(...pos); o.scale.set(...scale); o.castShadow=cast; o.receiveShadow=true; parent.add(o); return o;
}
function box(parent,material,pos,scale){return mesh(boxGeo,material,parent,pos,scale)}
function cylinder(parent,material,pos,r1,r2,h,segments=10){const o=mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material,parent,pos);return o}
function light(color,intensity,pos,distance=0,decay=2){const l=new THREE.PointLight(color,intensity,distance,decay);l.position.set(...pos);scene.add(l);return l}
const hemi=new THREE.HemisphereLight(0xb7c1bc,0x211c15,1.05);scene.add(hemi);
const moon=new THREE.DirectionalLight(0xd3d9d3,2.1);moon.position.set(-11,20,7);moon.castShadow=true;moon.shadow.mapSize.set(1536,1536);moon.shadow.camera.left=-22;moon.shadow.camera.right=22;moon.shadow.camera.top=30;moon.shadow.camera.bottom=-24;moon.shadow.bias=-.0002;scene.add(moon);
const fill=new THREE.DirectionalLight(0xb2c2bd,.65);fill.position.set(13,9,-14);scene.add(fill);

// Procedural dirt and stone, drawn locally so the whole scene works offline.
function noiseTexture(base, seed=3, stone=false){
  const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,256,256);
  let n=seed;const rand=()=>{n=(n*1664525+1013904223)>>>0;return n/4294967296};
  for(let i=0;i<stone?0:18000;i++){const a=rand();x.fillStyle=`rgba(${a>.5?190:0},${a>.5?180:0},${a>.5?150:0},${rand()*.16})`;x.fillRect(rand()*256,rand()*256,rand()*2+1,rand()*2+1)}
  if(stone)for(let i=0;i<150;i++){x.fillStyle=`rgba(220,210,185,${rand()*.13})`;x.fillRect(rand()*256,rand()*256,rand()*12+2,rand()*4+1)}
  const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(stone?1:9,stone?1:27);t.colorSpace=THREE.SRGBColorSpace;return t;
}
const dirtMat=new THREE.MeshStandardMaterial({map:noiseTexture('#39372f',4),roughness:1});
const roadMat=new THREE.MeshStandardMaterial({map:noiseTexture('#484239',8),roughness:1});
const wallMat=new THREE.MeshStandardMaterial({map:noiseTexture('#625a4c',17,true),roughness:1});
const ground=mesh(new THREE.PlaneGeometry(90,115),dirtMat,scene,[0,-.17,-14]);ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;
const road=mesh(new THREE.PlaneGeometry(7.5,73),roadMat,scene,[0,-.11,-19]);road.rotation.x=-Math.PI/2;road.receiveShadow=true;
// Pebbles, muddy ruts and scattered straw break the track silhouette.
let seed=33;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
for(let i=0;i<370;i++){
  const x=(rnd()-.5)*18,z=8-rnd()*53,s=.025+rnd()*.12;
  const m=mesh(sphereGeo,i%3?mats.stone:mats.wood,scene,[x,-.08+s*.15,z],[s*1.6,s*.38,s*.8],false);
  m.rotation.y=rnd()*3;
}
for(let side of [-1,1]){
  const hill=mesh(new THREE.SphereGeometry(1,18,14),mat(side<0?0x29302a:0x252a25),scene,[side*18,3,-23],[13,7,31],false);hill.receiveShadow=true;
  for(let i=0;i<38;i++){
    const x=side*(7+rnd()*14),z=10-rnd()*55,h=2+rnd()*3.5;
    makeTree(x,z,h,rnd());
  }
}

function makeTree(x,z,h,variant=0){
  const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);
  cylinder(g,mat(0x332b23),[0,h*.32,0],.16,.27,h*.67,8);
  const leafmat=mat(variant>.5?0x30382b:0x28332a);
  for(let i=0;i<5;i++){const y=h*(.38+i*.12),r=h*(.38-i*.045);const crown=mesh(new THREE.ConeGeometry(r,h*.43,9),leafmat,g,[(rnd()-.5)*.8,y,0],[1,1,1],true);crown.rotation.z=(rnd()-.5)*.18;}
  for(let i=0;i<4;i++){const branch=cylinder(g,mat(0x352c23),[(rnd()-.5)*.7,h*(.45+i*.08),0],.045,.09,h*.32,6);branch.rotation.z=(rnd()-.5)*1.1;}
}

function makeHouse(x,z,scale=1,variant=0){
 const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);g.scale.setScalar(scale);
 box(g,wallMat,[0,1.5,0],[5.3,3,4]);
 const timber=variant?mats.darkWood:mats.wood;
 for(const xx of [-2.45,-1.25,0,1.25,2.45])box(g,timber,[xx,1.5,2.04],[.15,3.1,.16]);
 box(g,timber,[0,.15,2.11],[5.2,.18,.18]);box(g,timber,[0,2.92,2.1],[5.3,.19,.18]);
 // Steep timber gable roof with deep overhangs.
 const roofmat=variant?mat(0x37362e):mats.roof;
 const left=mesh(new THREE.BoxGeometry(3.35,.17,4.9),roofmat,g,[-.82,3.39,0]);left.rotation.z=-.49;
 const right=mesh(new THREE.BoxGeometry(3.35,.17,4.9),roofmat,g,[.82,3.39,0]);right.rotation.z=.49;
 box(g,timber,[0,4.27,0],[.18,.18,4.95]);
 for(let k=0;k<8;k++){const zz=-2.2+k*.63;const a=box(g,mat(0x655a46),[-.85,3.45,zz],[.035,.13,.3]);a.rotation.z=-.49;const b=box(g,mat(0x655a46),[.85,3.45,zz],[.035,.13,.3]);b.rotation.z=.49;}
 // Recessed windows, crossbars and heavy lintels.
 for(const wx of [-1.6,1.6]){
  box(g,mats.darkWood,[wx,1.85,2.12],[.92,1.12,.18]);box(g,mats.glass,[wx,1.88,2.23],[.68,.78,.045]);
  box(g,timber,[wx-.39,1.88,2.28],[.06,.88,.08]);box(g,timber,[wx+.39,1.88,2.28],[.06,.88,.08]);box(g,timber,[wx,1.88,2.29],[.78,.06,.08]);box(g,timber,[wx,1.88,2.29],[.06,.78,.08]);
  box(g,timber,[wx,2.48,2.22],[1.04,.12,.28]);
 }
 // Offset door and stone lintel.
 box(g,mats.darkWood,[-.05,.95,2.17],[1.12,1.9,.2]);box(g,mat(0x4c3a2b),[-.05,.95,2.29],[.87,1.68,.08]);
 const knob=mesh(sphereGeo,mats.gold,g,[.25,.95,2.36],[.055,.055,.035]);
 for(let i=0;i<12;i++){const stone=mesh(boxGeo,i%2?mats.stone:wallMat,g,[-2.65+i*.49,.18,2.22],[.46,.32,.38]);stone.rotation.y=(rnd()-.5)*.15;}
 const lamp=light(0xffbd66,1.1,[x-2.1,2.25,z+2.55],8,1.8);lamp.castShadow=false;
 const bulb=mesh(sphereGeo,new THREE.MeshBasicMaterial({color:0xffd18a}),g,[-2.1,2.25,2.48],[.09,.12,.08],false);
 const awning=box(g,timber,[0,2.98,2.5],[5.5,.18,.35]);
 return g;
}
makeHouse(-7,-3,1,0);makeHouse(7,-10,1.08,1);makeHouse(-7.3,-17,.95,1);makeHouse(7.4,-25,1.1,0);
// Broken roadside fences and a hand-built shrine at the fork.
for(let side of [-1,1])for(let i=0;i<8;i++){
 const z=4-i*2.15,x=side*(4.7+(i%3)*.35);
 const post=box(scene,mats.wood,[x,.52,z],[.16,1.12,.16]);post.rotation.z=(rnd()-.5)*.12;
 if(i<7){const rail=box(scene,mats.darkWood,[side*5.2,.67,z-1.06],[1.25,.13,.12]);rail.rotation.z=(rnd()-.5)*.09;}
}
// Church silhouette and bell tower far down the lane.
const chapel=new THREE.Group();scene.add(chapel);chapel.position.set(0,0,-34);
box(chapel,wallMat,[0,2.2,0],[5.8,4.4,6]);
const chapelRoof1=mesh(new THREE.BoxGeometry(3.7,.22,6.8),mats.roof,chapel,[-.9,4.7,0]);chapelRoof1.rotation.z=-.48;
const chapelRoof2=mesh(new THREE.BoxGeometry(3.7,.22,6.8),mats.roof,chapel,[.9,4.7,0]);chapelRoof2.rotation.z=.48;
box(chapel,mats.wood,[0,5.4,-1.1],[1.6,4.8,1.6]);
const tower=mesh(new THREE.ConeGeometry(1.35,2.5,4),mats.roof,chapel,[0,9, -1.1]);tower.rotation.y=Math.PI/4;
box(chapel,mats.darkWood,[0,1.2,3.06],[1.25,2.4,.15]);
const crossV=box(chapel,mats.gold,[0,10.15,-1.1],[.12,1,.12]);box(chapel,mats.gold,[0,10.32,-1.1],[.6,.12,.12]);
for(const x of [-2.1,2.1])box(chapel,mats.wood,[x,2.1,3.08],[.16,4.2,.2]);
light(0xffa844,.65,[0,2.2,3.7],11,1.5);

// Character builder: articulated, layered clothing and expressive face details.
function makeHuman({coat=mats.coat,skin=mats.skin,hair=mats.hair,enemy=false,female=false}={}){
 const root=new THREE.Group(), rig=new THREE.Group();root.add(rig);
 const torso=mesh(new THREE.CapsuleGeometry(.37,.69,5,9),coat,rig,[0,1.49,0],[1,1, .68]);
 const pelvis=mesh(new THREE.BoxGeometry(.61,.35,.43),enemy?mats.trousers:mats.coatDark,rig,[0,.94,0]);
 const collar=mesh(new THREE.CylinderGeometry(.15,.21,.18,10),enemy?mats.red:mats.coatDark,rig,[0,1.97,0]);
 const neck=cylinder(rig,skin,[0,2.08,0],.105,.12,.27,10);
 const head=new THREE.Group();rig.add(head);head.position.set(0,2.36,0);
 mesh(new THREE.SphereGeometry(.25,18,16),skin,head,[0,0,0],[.83,1.06,.83]);
 // Jaw, nose, ears and inset eyes create a grounded human silhouette.
 mesh(new THREE.SphereGeometry(.17,14,10),skin,head,[0,-.1,-.005],[.86,.59,.79]);
 for(const s of [-1,1]){
  mesh(sphereGeo,skin,head,[s*.207,-.015,0],[.06,.095,.07]);
  mesh(sphereGeo,mat(0xddd0b6),head,[s*.094,.03,-.205],[.055,.034,.02],false);
  mesh(sphereGeo,enemy?mat(0x9d542d):mat(0x332c28),head,[s*.094,.03,-.223],[.022,.025,.014],false);
  mesh(sphereGeo,mats.hair,head,[s*.095,.079,-.226],[.068,.022,.025]);
  const brow=box(head,hair,[s*.095,.096,-.22],[.12,.035,.035]);brow.rotation.z=s*.11;
 }
 mesh(new THREE.ConeGeometry(.075,.19,7),skin,head,[0,-.005,-.225],[.75,1,1]);
 const cap=mesh(new THREE.SphereGeometry(.255,16,9,0,Math.PI*2,0,Math.PI*.52),hair,head,[0,.12,0],[1.02,1.05,1]);
 if(enemy){
  // Ragged hood, pallid skin and a dark, infected seam at the temple.
  const hood=mesh(new THREE.SphereGeometry(.285,14,10,0,Math.PI*2,0,Math.PI*.54),mats.coatDark,head,[0,.13,.012],[1.06,1.08,1.04]);
