import * as THREE from '../vendor/three.module.js';

const $ = s => document.querySelector(s);
const canvas = $('#game');
const scene = new THREE.Scene();
const fog = new THREE.Color(0x171f1d);
scene.background = fog;
scene.fog = new THREE.FogExp2(fog, 0.021);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 150);
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.6)); renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.15;
renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
const mat = (c,r=.85,m=0) => new THREE.MeshStandardMaterial({color:c,roughness:r,metalness:m});
const M = {wood:mat(0x40372c), dark:mat(0x292a23), stone:mat(0x625e51), roof:mat(0x302d28), metal:mat(0x55574f,.58,.5), skin:mat(0x98745c), hair:mat(0x282522), coat:mat(0x38443d), coat2:mat(0x242b28), pants:mat(0x292d2b), boot:mat(0x171a18), red:mat(0x75463b), bone:mat(0xa59779), glass:mat(0x171d1a,.27,.15), gold:mat(0xb3945f,.5,.5)};
const boxGeo = new THREE.BoxGeometry(1,1,1), sphereGeo = new THREE.SphereGeometry(1,14,10);
function mesh(g,m,p,pos=[0,0,0],scale=[1,1,1],cast=true){const o=new THREE.Mesh(g,m);o.position.set(...pos);o.scale.set(...scale);o.castShadow=cast;o.receiveShadow=true;p.add(o);return o;}
function box(p,m,pos,scale){return mesh(boxGeo,m,p,pos,scale)}
function cyl(p,m,pos,r1,r2,h,n=9){return mesh(new THREE.CylinderGeometry(r1,r2,h,n),m,p,pos)}
function point(color,intensity,pos,distance=0){const l=new THREE.PointLight(color,intensity,distance,1.8);l.position.set(...pos);scene.add(l);return l;}
scene.add(new THREE.HemisphereLight(0xb7c1bc,0x211c15,1.05));
const moon=new THREE.DirectionalLight(0xd3d9d3,2);moon.position.set(-11,20,7);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-22;moon.shadow.camera.right=22;moon.shadow.camera.top=30;moon.shadow.camera.bottom=-24;scene.add(moon);
const fill=new THREE.DirectionalLight(0xb2c2bd,.6);fill.position.set(13,9,-14);scene.add(fill);
let seed=33;const rnd=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
function texture(base,stone=false){const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d');x.fillStyle=base;x.fillRect(0,0,128,128);for(let i=0;i<(stone?100:3500);i++){const a=rnd();x.fillStyle=`rgba(${a>.5?190:0},${a>.5?180:0},${a>.5?150:0},${rnd()*.15})`;x.fillRect(rnd()*128,rnd()*128,rnd()*3+1,rnd()*2+1);}const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(stone?1:8,stone?1:22);t.colorSpace=THREE.SRGBColorSpace;return t;}
const groundMat=new THREE.MeshStandardMaterial({map:texture('#39372f'),roughness:1}), roadMat=new THREE.MeshStandardMaterial({map:texture('#484239'),roughness:1}), wallMat=new THREE.MeshStandardMaterial({map:texture('#625a4c',true),roughness:1});
const ground=mesh(new THREE.PlaneGeometry(90,115),groundMat,scene,[0,-.17,-14]);ground.rotation.x=-Math.PI/2;
const road=mesh(new THREE.PlaneGeometry(7.5,73),roadMat,scene,[0,-.11,-19]);road.rotation.x=-Math.PI/2;
for(let i=0;i<250;i++){const x=(rnd()-.5)*16,z=8-rnd()*53,s=.025+rnd()*.12;mesh(sphereGeo,i%3?M.stone:M.wood,scene,[x,-.08,z],[s*1.6,s*.38,s*.8],false);}
function tree(x,z,h){const g=new THREE.Group();scene.add(g);g.position.set(x,0,z);cyl(g,mat(0x332b23),[0,h*.32,0],.16,.27,h*.67,8);for(let i=0;i<5;i++){mesh(new THREE.ConeGeometry(h*(.38-i*.045),h*.43,8),mat(0x293329),g,[(rnd()-.5)*.6,h*(.38+i*.12),0]);}}
for(const side of [-1,1]){mesh(new THREE.SphereGeometry(1,16,12),mat(0x29302a),scene,[side*18,3,-23],[13,7,31],false);for(let i=0;i<30;i++)tree(side*(7+rnd()*14),10-rnd()*55,2+rnd()*3.5);}
