input.newString:
const state={mode:'menu',health:100,ammo:12,reserve:36,kits:1,kills:0,yaw:0,keys:{},last:performance.now(),time:0,shotCooldown:0,reload:0,toastTimer:0,mouseLocked:false,stepPhase:0,interactCooldown:0};
function toast(text,ms=2000){$('#toast').textContent=text;$('#toast').classList.add('show');state.toastTimer=ms/1000;}
function objective(text,banner,sub){$('#objective').textContent=text;const el=$('#objective-banner');el.querySelector('b').textContent=banner;el.querySelector('small').textContent=sub;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3600);}
function updateHealth(){state.health=Math.max(0,Math.min(100,state.health));$('#health-fill').style.width=state.health+'%';$('#health-text').textContent=Math.ceil(state.health);}
function updateAmmo(){$('#ammo-mag').textContent=state.ammo;$('#ammo-reserve').textContent=state.reserve;}
function briefing(){if(state.mode!=='menu')return;state.mode='briefing';$('#intro').classList.add('hidden');$('#briefing').classList.remove('hidden');}
function start(){if(state.mode!=='briefing')return;state.mode='playing';$('#briefing').classList.add('hidden');$('#hud').classList.remove('hidden');objective('Encuentra la señal de Alma','EL PUEBLO ESTÁ EN SILENCIO.','ENCUENTRA EL ORIGEN DE LA SEÑAL');toast('Noxvill: «Alma, aguanta. Ya estoy aquí.»',3500);canvas.requestPointerLock?.();}
$('#start').addEventListener('click',briefing);$('#deploy').addEventListener('click',start);$('#restart').addEventListener('click',()=>location.reload());
window.addEventListener('keydown',e=>{if(['KeyW','KeyA','KeyS','KeyD','Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();state.keys[e.code]=true;if(e.code==='Enter'){if(state.mode==='menu')briefing();else if(state.mode==='briefing')start();else if(state.mode==='ended')location.reload();}if(e.code==='KeyR'&&state.mode==='playing')reload();if(e.code==='KeyF'&&state.mode==='playing')heal();if(e.code==='KeyE'&&state.mode==='playing')interact();});
window.addEventListener('keyup',e=>state.keys[e.code]=false);window.addEventListener('blur',()=>state.keys={});
canvas.addEventListener('click',()=>{if(state.mode==='playing'&&!document.pointerLockElement)canvas.requestPointerLock?.();else if(state.mode==='playing')shoot();});window.addEventListener('mousedown',e=>{if(e.button===0&&state.mode==='playing'&&document.pointerLockElement)shoot();});
document.addEventListener('pointerlockchange',()=>state.mouseLocked=document.pointerLockElement===canvas);document.addEventListener('mousemove',e=>{if(state.mode==='playing'&&state.mouseLocked)state.yaw=THREE.MathUtils.clamp(state.yaw-e.movementX*.0022,-1.48,1.48);});
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setSize(innerWidth,innerHeight);});
function reload(){if(state.reload>0||state.ammo===12||state.reserve<=0)return;state.reload=1.05;toast('RECARGANDO…',800);}
function heal(){if(state.kits<=0){toast('No te quedan botiquines.',1600);return;}if(state.health>=100){toast('No necesitas curarte todavía.',1500);return;}state.kits--;state.health+=42;updateHealth();toast('BOTIQUÍN UTILIZADO · SALUD RESTAURADA',2200);}
const raycaster=new THREE.Raycaster();
function shoot(){if(state.mode!=='playing'||state.shotCooldown>0||state.reload>0)return;if(!state.ammo){toast('Sin munición. Pulsa R para recargar.',1800);state.shotCooldown=.3;return;}state.ammo--;updateAmmo();state.shotCooldown=.24;const dir=new THREE.Vector3(Math.sin(state.yaw),0,-Math.cos(state.yaw));raycaster.set(camera.position,dir);raycaster.far=31;const hits=raycaster.intersectObjects(enemies.filter(e=>e.alive).map(e=>e.torso),false);if(hits.length){const e=enemies.find(x=>x.torso===hits[0].object);if(e){e.hp--;e.hit=.18;e.rig.rotation.x=-.18;toast(e.hp?'IMPACTO — EL INFECTADO SIGUE EN PIE':'OBJETIVO NEUTRALIZADO',1100);if(e.hp<=0){e.alive=false;e.root.rotation.x=-Math.PI/2;e.root.position.y=.12;state.kills++;if(state.kills===2)objective('Avanza hasta la capilla','LA VÍA A LA CAPILLA ESTÁ LIBRE.','NO BAJES LA GUARDIA');if(state.kills===4)toast('Noxvill: «Demasiados… y ninguno está muerto del todo.»',2600);}}}$('#crosshair').classList.add('firing');setTimeout(()=>$('#crosshair').classList.remove('firing'),95);muzzle.visible=true;flash.intensity=8;setTimeout(()=>{muzzle.visible=false;flash.intensity=0;},65);}
function interact(){if(state.interactCooldown>0)return;state.interactCooldown=.5;const p=player.root.position;for(const k of medkits)if(!k.taken&&p.distanceTo(k.group.position)<1.9){k.taken=true;k.group.visible=false;state.kits++;toast('BOTIQUÍN RECOGIDO · PULSA F PARA USAR',2400);return;}if(p.distanceTo(radio.position)<2.5){if(state.kills<2){toast('El transmisor está atascado. Hay infectados cerca…',2300);return;}finish();return;}toast('No hay nada que puedas usar aquí.',1400);}
function finish(){state.mode='ended';document.exitPointerLock?.();$('#end-title').textContent='La señal continúa.';$('#end-copy').textContent='El transmisor se abre con un chasquido. Entre la estática surge la voz de Alma: «Nox… ya están en la puerta.» A lo lejos, la campana de la capilla empieza a sonar. La noche apenas comienza.';$('#end-screen').classList.remove('hidden');}
function gameOver(){state.mode='ended';document.exitPointerLock?.();$('#end-title').textContent='La sierra te reclama.';$('#end-copy').textContent='San Aureliano guarda silencio una vez más. Pero la señal sigue transmitiendo… Vuelve a intentarlo.';$('#end-screen').classList.remove('hidden');}
function updatePrompt(){const p=player.root.position;let t='';for(const k of medkits)if(!k.taken&&p.distanceTo(k.group.position)<2.05)t='[ E ]  RECOGER BOTIQUÍN';if(p.distanceTo(radio.position)<2.5)t=state.kills<2?'[ E ]  SEÑAL DE RADIO · AMENAZA ACTIVA':'[ E ]  ESCUCHAR LA SEÑAL';$('#prompt').textContent=t;$('#prompt').classList.toggle('visible',!!t);}
function movePlayer(dt){if(state.mode!=='playing')return;const k=state.keys;let f=(k.KeyW||k.ArrowUp?1:0)-(k.KeyS||k.ArrowDown?1:0),s=(k.KeyD||k.ArrowRight?1:0)-(k.KeyA||k.ArrowLeft?1:0);const moving=!!(f||s),len=Math.hypot(f,s)||1;f/=len;s/=len;const speed=k.ShiftLeft||k.ShiftRight?4.7:3.05;const fx=Math.sin(state.yaw),fz=-Math.cos(state.yaw),rx=Math.cos(state.yaw),rz=Math.sin(state.yaw);player.root.position.x=THREE.MathUtils.clamp(player.root.position.x+(fx*f+rx*s)*speed*dt,-3.3,3.3);player.root.position.z=THREE.MathUtils.clamp(player.root.position.z+(fz*f+rz*s)*speed*dt,-32,7.5);if(moving){const target=Math.atan2(s,Math.max(.05,f))+state.yaw;let d=THREE.MathUtils.euclideanModulo(target-player.root.rotation.y+Math.PI,Math.PI*2)-Math.PI;player.root.rotation.y+=d*Math.min(1,dt*9);state.stepPhase+=dt*(speed===4.7?13:9);player.legs[0].rotation.x=Math.sin(state.stepPhase)*.48;player.legs[1].rotation.x=-Math.sin(state.stepPhase)*.48;}else player.legs.forEach(l=>l.rotation.x*=.8);camera.position.set(player.root.position.x-Math.sin(state.yaw)*4.5,3,player.root.position.z+Math.cos(state.yaw)*4.5);camera.lookAt(player.root.position.x+Math.sin(state.yaw)*2,1.75,player.root.position.z-Math.cos(state.yaw)*2);}

