import { createRequire } from 'node:module';
const requireFromRuntime = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = requireFromRuntime('playwright');
(async () => {
  const browser = await chromium.launch({
    executablePath: '/usr/bin/chromium', headless: true,
    args: ['--no-sandbox', '--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=swiftshader', '--use-gl=angle', '--disable-dev-shm-usage']
  });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
  const errors = [];
  page.on('pageerror', e => errors.push(`pageerror: ${e.message}`));
  page.on('console', m => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
  page.on('requestfailed', r => errors.push(`requestfailed: ${r.url()} ${r.failure()?.errorText}`));
  page.on('response', r => { if (r.status() >= 400) errors.push(`http ${r.status()}: ${r.url()}`); });
  await page.goto('http://127.0.0.1:3000', { waitUntil: 'networkidle' });
  await page.waitForTimeout(2300);
  console.log('LOAD CLASS', await page.locator('#loading').getAttribute('class'));
  console.log('TITLE', await page.title());
  console.log('INTRO', await page.locator('#intro').isVisible(), 'LOADING', await page.locator('#loading').getAttribute('class'));
  await page.screenshot({path:'/home/runner/work/MexZombie/MexZombie/noxvill-capture.jpg',type:'jpeg',quality:85,timeout:90000});
  await page.locator('#start').click();
  await page.waitForTimeout(300);
  console.log('BRIEFING CLASSES', await page.locator('#briefing').getAttribute('class'), 'STYLE', await page.locator('#briefing').evaluate(e => `${getComputedStyle(e).visibility}/${getComputedStyle(e).opacity}`));
  await page.screenshot({path:'/tmp/opencode/noxvill-briefing.jpg',type:'jpeg',quality:85});
  await page.locator('#deploy').click();
  await page.waitForTimeout(400);
  console.log('HUD', await page.locator('#hud').isVisible(), 'OBJECTIVE', await page.locator('#objective').innerText());
  await page.locator('#game').click();
  await page.mouse.click(640, 400);
  await page.keyboard.down('w'); await page.waitForTimeout(1000); await page.keyboard.up('w');
  await page.keyboard.press('r'); await page.waitForTimeout(1300);
  await page.mouse.click(640, 400); await page.waitForTimeout(250);
  console.log('HEALTH', await page.locator('#health-text').innerText(), 'AMMO', await page.locator('#ammo-mag').innerText(), '/', await page.locator('#ammo-reserve').innerText(), 'LOCK', await page.evaluate(() => !!document.pointerLockElement));
  await page.screenshot({path:'/tmp/opencode/noxvill-game.jpg',type:'jpeg',quality:85});
  console.log('ERRORS', JSON.stringify(errors));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

